products=[('numero-habitacion','Números de habitación','Identificación para espacios de alojamiento.','hero','Señal de habitación 204 en acrílico oscuro','Señalización','Número, tipografía, formato y acabado según evaluación.'),('exhibidor-acrilico','Exhibidores en acrílico','Presenta información en recepción, mesas o mostradores.','display','Exhibidor conceptual de acrílico transparente','Acrílico','Formato, medidas y aplicación gráfica según evaluación.'),('placa-personalizada','Placas personalizadas','Una pieza para identificar y comunicar.','pictograma','Pictograma de baño en acrílico con película protectora','Fabricación a medida','Texto, diseño, medidas y sistema de colocación según evaluación.')]
