 return '<div class="product-grid">'+''.join(f'<a class="product" href="producto-{p[0]}.html">{image(p[3],p[4])}<span class="eyebrow">{p[5]}</span><h3>{p[1]}</h3><p>{p[2]}</p><span class="text-link">Ver detalles ↗</span></a>' for p in products)+'</div>'
